    if(dive>=3&&(ad||cls==="mage"||cls==="leth"||cls==="ench"||cls==="tsup")){
      const why=`Leur compo mise sur l'engage et le dive (${lst([...new Set([...E.engage,...E.assaAD,...E.assaAP])])}) : `;
      if(ad) ops.push({it:E.assaAD.length>=2?"Immortal Shieldbow":"Guardian Angel",at:B_MIN.def[cls],prio:6,why:why+(E.assaAD.length>=2?"Immortal Shieldbow en %P contre le burst":"Guardian Angel en %P pour survivre à l'engage")});
      else if(cls==="mage") ops.push({it:E.ap>E.ad+1?"Banshee's Veil":"Zhonya's Hourglass",at:E.assaAD.length+E.assaAP.length>=2?1:2,prio:6,why:why+(E.ap>E.ad+1?"Banshee's Veil":"Zhonya's Hourglass")+" en %P"});
      else if(cls==="leth") ops.push({it:"Edge of Night",at:B_MIN.def.leth,prio:5,why:why+"Edge of Night en %P"});
      else if(cls==="ench") ops.push({it:E.supp.length||E.engage.length>=3?"Mikael's Blessing":"Locket of the Iron Solari",at:1,prio:6,why:why+(E.supp.length||E.engage.length>=3?"Mikael's Blessing en %P pour retirer les contrôles de notre carry":"Locket of the Iron Solari en %P pour encaisser l'engage")});
      else if(cls==="tsup") ops.push({it:"Knight's Vow",at:1,prio:4,why:why+"Knight's Vow en %P, lié à notre carry"}); }
    // 5. Carries adverses critiques / auto-attaques : armure anti-crit chez nos tanks et bruisers
