      const it=cls==="tank"?"Kaenic Rookern":cls==="tsup"?"Kaenic Rookern":cls==="onhit"?"Wit's End":(CHAMPS[o.name]&&CHAMPS[o.name].dmg==="AP"?"Spirit Visage":"Maw of Malmortius");
